fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cw: i32 = w / 8;
    let ch: i32 = h / 8;
    let mut cy: i32 = 0;
    while cy < 8 {
        let mut cx: i32 = 0;
        while cx < 8 {
            let mut c: i32 = 0x202020;
            if (cx + cy) % 2 == 0 { c = 0xd0d0d0; }
            host::display::fill_rect(cx * cw, cy * ch, cw, ch, c);
            cx = cx + 1;
        }
        cy = cy + 1;
    }
    host::display::present();
}
